// Generates src/lib/build-info.ts (embedded in the client bundle) and
// public/version.json (served at /version.json so installed apps can detect
// a newer deployed version). Run automatically before `next dev` / `next build`.
//
// The buildId is a deterministic hash of the committed source (excluding the
// generated files themselves). This guarantees version.json, the embedded
// APP_BUILD_ID and the bundled app.zip always share the SAME buildId — even
// when Vercel re-runs this script at deploy time — so installed apps never
// see an "update available" loop caused by clock-skewed rebuilds.
import { readFileSync, writeFileSync, existsSync, readdirSync, statSync } from "node:fs";
import { resolve, join, relative } from "node:path";
import { createHash } from "node:crypto";

const pkg = JSON.parse(readFileSync(resolve("package.json"), "utf8"));

const HASH_DIRS = ["src", "public", "scripts"];
const HASH_FILES = [
  "package.json",
  "next.config.ts",
  "next.config.mjs",
  "capacitor.config.ts",
  "capacitor.config.json",
];
const EXCLUDED_NAMES = new Set(["app.zip", "version.json", "build-info.ts"]);

const files = [];
function collect(dir) {
  for (const entry of readdirSync(dir)) {
    if (EXCLUDED_NAMES.has(entry)) continue;
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) collect(full);
    else files.push(full);
  }
}
for (const dir of HASH_DIRS) {
  if (existsSync(resolve(dir))) collect(resolve(dir));
}
for (const file of HASH_FILES) {
  if (existsSync(resolve(file))) files.push(resolve(file));
}

const hash = createHash("sha256");
for (const file of files.sort()) {
  // Normalize path separators so the hash is identical on Windows and
  // Linux (path.relative() returns backslashes on Windows, slashes on Linux).
  hash.update(relative(process.cwd(), file).replace(/\\/g, "/"));
  // Normalize line endings so the hash is identical whether the checkout has
  // LF (Linux/Vercel, git autocrlf=off) or CRLF (Windows, autocrlf=true).
  // Without these, a freshly built APK's embedded build id never matches the
  // deployed /version.json, so the app always claims an update is available.
  hash.update(readFileSync(file).toString().replace(/\r/g, ""));
}
const buildId = hash.digest("hex").slice(0, 7);

const version = String(pkg.version ?? "0.0.0");

writeFileSync(
  resolve("src/lib/build-info.ts"),
  [
    "// AUTO-GENERATED by scripts/gen-version.mjs — do not edit.",
    `export const APP_VERSION = ${JSON.stringify(version)};`,
    `export const APP_BUILD_ID = ${JSON.stringify(buildId)};`,
    "",
  ].join("\n")
);

writeFileSync(
  resolve("public/version.json"),
  JSON.stringify({ version, buildId }, null, 2)
);

console.log(`Generated build info: v${version} (${buildId})`);